// #3257d0efcc42561f5bc1ef6c — короткий вариант для регулярного регресса (~2.5 мин звонка, ~6–8 мин всего):
// звонок завершает кандидат; все части записи загружены, end-candidate-attempt быстрый, транскрипт ≤ 300 с,
// отчёт ready, файл ≈ звонку, клик по последней реплике ставит плеер. Кейс REC-003.
// Параллельность склейки короткий звонок НЕ доказывает (мало частей) — это делает REC-002 (@slow, 20 мин).
// @data, НЕ prod-safe: создаёт кандидата «QA-AUTO-REC-…» (link_only, без письма/SMS), тратит официальный звонок и AI.
// Кандидат не удаляется (правило проекта — только с «да»). Симуляция: QA_CALL_SIMULATION (по умолчанию «מערכות סולאריות»).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink, tap } from '../candidate-call/support';
import { launchGuest, startOfficialCall, okParts, expectAllPartsUploaded, openBusinessApi, candidateId, waitTranscriptAndReport, checkReportPage } from './support';

const PARTS_BEFORE_END = 30; // часть ≈ каждые 5 с → ~2.5 мин разговора

test.describe('Запись звонка — склейка частей и транскрипт после длинного звонка (#3257d0efcc42561f5bc1ef6c) @call', () => {
  test('короткий звонок ~2.5 мин, конец кандидатом: части без пропусков, end-candidate-attempt < 30 с, транскрипт ≤ 300 с, отчёт ready, файл ≈ звонку, клик по последней реплике @desktop @data #3257d0efcc42561f5bc1ef6c', async ({ asUser }) => {
    test.setTimeout(20 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-REC-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (официальный звонок использован), не удаляется` });

    const guest = await launchGuest();
    try {
      await startOfficialCall(guest.page, link);
      await expect
        .poll(() => okParts(guest.log).size, { message: `меньше ${PARTS_BEFORE_END} частей записи`, timeout: 5 * 60_000, intervals: [2_000] })
        .toBeGreaterThanOrEqual(PARTS_BEFORE_END);
      await tap(guest.page, 'לסיים שיחה');
      await tap(guest.page, 'לאשר סיום שיחה');
      await expect(guest.page.getByText('הסימולציה הושלמה')).toBeVisible({ timeout: 120_000 });
      await expect.poll(() => guest.log.endRespAt, { message: 'нет ответа end-candidate-attempt', timeout: 120_000 }).toBeTruthy();

      // Источник: AC «איחוד חלקי ההקלטה אינו מוריד את החלקים בזה אחר זה … נשאר מרווח ביטחון בתקציב».
      const stitchSec = (guest.log.endRespAt! - guest.log.endReqAt!) / 1000;
      expect(guest.log.endStatus).toBe(200);
      expect(stitchSec, `end-candidate-attempt ${stitchSec.toFixed(1)} с`).toBeLessThan(30);
      expect(guest.log.endBody?.recording?.is_partial).toBe(false);

      // F-36 AC1 «הקלטת השיחה במלואה».
      const parts = await expectAllPartsUploaded(guest.log);
      expect(parts).toBeGreaterThanOrEqual(PARTS_BEFORE_END);

      const api = await openBusinessApi(business);
      const id = await candidateId(api, name);
      const { report, transcriptSec, reportSec } = await waitTranscriptAndReport(api, id);
      expect(report.attempt?.duration_seconds, 'длительность звонка').toBeGreaterThanOrEqual(120);
      expect(transcriptSec).toBeLessThanOrEqual(300); // AC «התמלול מוכן בתוך 300 שניות מסוף השיחה»
      expect(reportSec).toBeLessThanOrEqual(600); // decisions «סך הזמן עד דוח מוכן אינו עולה על 10 דקות»

      const page = await checkReportPage(business, id, report);
      test.info().annotations.push({
        type: 'timing',
        description: `частей ${parts}, склейка ${stitchSec.toFixed(1)} с, транскрипт ≤ +${transcriptSec.toFixed(0)} с, отчёт +${reportSec.toFixed(0)} с, файл ${page.decodedSec.toFixed(1)} с / звонок ${report.attempt?.duration_seconds} с, сегментов ${page.segments}`,
      });
    } finally {
      await guest.browser.close();
    }
  });
});
